// Tag: Set Up the Meadow
// Run with "The Meadow: Tag" as the viewed scene. Safe to run twice: it skips anything already there.
const MOD = "missing-features";
const scene = canvas.scene;
if (!scene) return ui.notifications.warn("Open The Meadow: Tag scene first.");
const C = 1400, PX = 20; // map center and pixels per foot
const at = (deg, ft) => ({ x: C + Math.cos(deg * Math.PI / 180) * ft * PX, y: C + Math.sin(deg * Math.PI / 180) * ft * PX });

const folderFor = async type =>
  game.folders.find(f => f.type === type && f.name === "Tag") ?? Folder.create({ name: "Tag", type });
const actorFolder = await folderFor("Actor");
const tableFolder = await folderFor("RollTable");

// 1. Roll tables: import any that aren't in the world yet
const tablePack = game.packs.get(`${MOD}.tables`);
for (const e of await tablePack.getIndex()) {
  if (!game.tables.getName(e.name)) await game.tables.importFromCompendium(tablePack, e._id, { folder: tableFolder.id });
}

// 2. NPC actors (and The Field, from the tag encounter's actors) and their tokens
const packs = [game.packs.get(`${MOD}.npcs`), game.packs.get(`${MOD}.encounter-actors`)];
async function getNpc(name) {
  const have = game.actors.getName(name);
  if (have) return have;
  for (const pack of packs) {
    const entry = (await pack.getIndex()).find(i => i.name === name);
    if (entry) return game.actors.importFromCompendium(pack, entry._id, { folder: actorFolder.id });
  }
  throw new Error(`No actor named "${name}" in the module's compendiums.`);
}

const size = canvas.grid.size;
// place(actor name, token position): the token shows only the character's name, never the version
async function place(name, pos, extra = {}) {
  const existing = scene.tokens.find(t => t.actor?.name === name);
  if (existing) return existing;
  const actor = await getNpc(name);
  const w = actor.prototypeToken.width * size;
  const td = await actor.getTokenDocument({ x: pos.x - w / 2, y: pos.y - w / 2, ...extra });
  const [token] = await scene.createEmbeddedDocuments("Token", [td.toObject()]);
  return token;
}
await place("The Grandfather", { x: C, y: C + 22 * PX });
await place("Lyra (Moon Child)", { x: C - 20 * PX, y: C - 17 * PX });
await place("Syraa (Moon Child)", { x: C - 25 * PX, y: C + 12 * PX });
const ruka = await place("Ruka (Moon Child)", { x: C + 25 * PX, y: C + 10 * PX });
const field = await place("The Field", { x: 150, y: 150 }, { hidden: true });

// 3. Regions for the folds and lag patches (GM-only outlines over the painted map)
const regions = [
  ...[[25, 42], [130, 40], [200, 44], [320, 40]].map(([a, d], i) => ({ name: `Fold ${i + 1}`, color: "#b48cff", ...at(a, d), rx: 5, ry: 5 })),
  ...[[75, 46], [255, 44]].map(([a, d], i) => ({ name: `Lag Patch ${i + 1}`, color: "#e6aa3c", ...at(a, d), rx: 11, ry: 8 }))
];
try {
  const missing = regions.filter(r => !scene.regions?.find(x => x.name === r.name));
  if (missing.length) await scene.createEmbeddedDocuments("Region", missing.map(r => ({
    name: r.name, color: r.color, visibility: CONST.REGION_VISIBILITY?.GAMEMASTER ?? 1,
    shapes: [{ type: "ellipse", x: r.x, y: r.y, radiusX: r.rx * PX, radiusY: r.ry * PX, rotation: 0, hole: false }]
  })));
} catch (err) {
  console.warn(err);
  ui.notifications.warn("Couldn't draw the fold and lag-patch regions. Use the GM map for those instead.");
}

// 4. The encounter: The Field always acts first, then everyone rolls
let combat = game.combats.find(c => c.scene?.id === scene.id);
if (!combat) combat = await Combat.create({ scene: scene.id, active: true });
const already = new Set(combat.combatants.map(c => c.tokenId));
const add = [field, ruka].filter(t => !already.has(t.id));
if (add.length) await combat.createEmbeddedDocuments("Combatant",
  add.map(t => ({ tokenId: t.id, sceneId: scene.id, actorId: t.actorId, hidden: t.hidden })));
const fieldC = combat.combatants.find(c => c.tokenId === field.id);
if (fieldC && fieldC.initiative == null) await combat.setInitiative(fieldC.id, 99);

ui.notifications.info("Meadow ready. Add the players to the tracker, roll initiative, Begin Combat, then run Tag: Start of Round each round.");
